import {
  DEFAULT_DOC_KIND,
  NO_BINDING,
  workingDocKey
} from "./instance-working-document.slice.js";
import { selectPreferredScratchpadId } from "../../../../host/prefs.js";
const entryOf = (state, conversationId, kind) => state.instanceWorkingDocument.byKey[workingDocKey(conversationId, kind)];
const selectWorkingDocEntry = (conversationId, kind = DEFAULT_DOC_KIND) => (state) => entryOf(state, conversationId, kind);
const selectWorkingDocEnabled = (conversationId, kind = DEFAULT_DOC_KIND) => (state) => (
  // OPT-IN: off unless an entry says otherwise. The durable on/off is
  // restored from the cx_conversation_documents junction on mount; absent
  // any entry the document is off.
  entryOf(state, conversationId, kind)?.enabled ?? false
);
const selectWorkingDocContent = (conversationId, kind = DEFAULT_DOC_KIND) => (state) => entryOf(state, conversationId, kind)?.content ?? "";
const selectWorkingDocTitle = (conversationId, kind = DEFAULT_DOC_KIND) => (state) => (
  // Empty by default — the document is "unnamed" until the user names it.
  // Display surfaces fall back ("Working document" / "Scratchpad") for an
  // empty title; we never persist that fallback as a real title.
  entryOf(state, conversationId, kind)?.title ?? ""
);
const selectWorkingDocBinding = (conversationId, kind = DEFAULT_DOC_KIND) => (state) => entryOf(state, conversationId, kind)?.binding ?? NO_BINDING;
const selectWorkingDocSaving = (conversationId, kind = DEFAULT_DOC_KIND) => (state) => entryOf(state, conversationId, kind)?.saving ?? false;
const selectWorkingDocError = (conversationId, kind = DEFAULT_DOC_KIND) => (state) => entryOf(state, conversationId, kind)?.lastError ?? null;
const selectWorkingDocAgentRevision = (conversationId, kind = DEFAULT_DOC_KIND) => (state) => entryOf(state, conversationId, kind)?.agentRevision ?? 0;
const selectWorkingDocMaterialized = (conversationId, kind = DEFAULT_DOC_KIND) => (state) => entryOf(state, conversationId, kind)?.materialized ?? false;
const selectWorkingDocVersion = (conversationId, kind = DEFAULT_DOC_KIND) => (state) => entryOf(state, conversationId, kind)?.version ?? 0;
const selectActiveScratchpadId = (state) => selectPreferredScratchpadId(state);
const NO_ATTACHED = [];
const selectAttachedScratchpadIds = (conversationId) => (state) => state.instanceWorkingDocument.attachedScratchByConversation[conversationId] ?? NO_ATTACHED;
const selectWorkingDocConflict = (conversationId, kind = DEFAULT_DOC_KIND) => (state) => entryOf(state, conversationId, kind)?.conflict ?? null;
export {
  selectActiveScratchpadId,
  selectAttachedScratchpadIds,
  selectWorkingDocAgentRevision,
  selectWorkingDocBinding,
  selectWorkingDocConflict,
  selectWorkingDocContent,
  selectWorkingDocEnabled,
  selectWorkingDocEntry,
  selectWorkingDocError,
  selectWorkingDocMaterialized,
  selectWorkingDocSaving,
  selectWorkingDocTitle,
  selectWorkingDocVersion
};
