const WORKING_DOCUMENT_CONTEXT_KEY = "working_document";
const WORKING_DOCUMENT_LABEL = "Working Document";
const WORKING_DOCUMENT_DESCRIPTION = "The collaborative working document you build with the user. Read it with ctx_get(working_document); apply every change with ctx_patch on working_document. Never discard the user's content.";
const USER_SCRATCHPAD_CONTEXT_KEY = "user_scratchpad";
const USER_SCRATCHPAD_LABEL = "My Scratchpad";
const USER_SCRATCHPAD_DESCRIPTION = "The user's private scratchpad. READ-ONLY: you may read it with ctx_get(user_scratchpad) to understand what the user is thinking about, but you must NEVER modify it. It belongs to the user alone.";
const DOC_CONTEXT_KINDS = {
  [WORKING_DOCUMENT_CONTEXT_KEY]: "working",
  [USER_SCRATCHPAD_CONTEXT_KEY]: "scratch"
};
const USER_SCRATCHPAD_EXTRA_PREFIX = `${USER_SCRATCHPAD_CONTEXT_KEY}_`;
function scratchpadExtraContextKey(documentId) {
  return `${USER_SCRATCHPAD_EXTRA_PREFIX}${documentId.slice(0, 8)}`;
}
function docKindForContextKey(key) {
  const direct = DOC_CONTEXT_KINDS[key];
  if (direct) return direct;
  if (key.startsWith(USER_SCRATCHPAD_EXTRA_PREFIX)) return "scratch";
  return null;
}
function sourceKindFor(binding) {
  switch (binding.kind) {
    case "cx_working_document":
      return "working_document";
    case "note":
      return "note";
    case "studio_document":
      return "studio_document";
    default:
      return "working_document";
  }
}
function buildWorkingDocumentContextValue(args) {
  const { content, binding, conversationId, organizationId, docKind, title, version } = args;
  const id = binding.id;
  if (!id) {
    return {
      content,
      mutable: false,
      persist: "client",
      type: "text",
      label: WORKING_DOCUMENT_LABEL,
      description: WORKING_DOCUMENT_DESCRIPTION,
      max_inline_chars: 0
    };
  }
  const kind = sourceKindFor(binding);
  const source = {
    kind,
    id,
    field: "content",
    base_version: version
  };
  if (kind === "working_document") {
    source.materialize = {
      organization_id: organizationId,
      conversation_id: conversationId,
      kind: docKind,
      title
    };
  }
  return {
    content,
    mutable: true,
    persist: "auto",
    type: "text",
    label: WORKING_DOCUMENT_LABEL,
    description: WORKING_DOCUMENT_DESCRIPTION,
    source,
    max_inline_chars: 0
  };
}
function buildUserScratchpadContextValue(content, label) {
  return {
    content,
    mutable: false,
    persist: "client",
    type: "text",
    label: label?.trim() || USER_SCRATCHPAD_LABEL,
    description: USER_SCRATCHPAD_DESCRIPTION,
    max_inline_chars: 0
  };
}
export {
  DOC_CONTEXT_KINDS,
  USER_SCRATCHPAD_CONTEXT_KEY,
  USER_SCRATCHPAD_EXTRA_PREFIX,
  USER_SCRATCHPAD_LABEL,
  WORKING_DOCUMENT_CONTEXT_KEY,
  WORKING_DOCUMENT_LABEL,
  buildUserScratchpadContextValue,
  buildWorkingDocumentContextValue,
  docKindForContextKey,
  scratchpadExtraContextKey
};
